// Chapters and their levels. The levels themselves are generated by
// scripts/generate-levels.ts (stored in levels.json) and every one is
// re-checked by tests/levels.test.ts with the solver.

import generated from './levels.json';

export interface PathGoal {
  kind: 'path';
  from: string; // the piece that moves
  target: string;
  moves: number; // must equal the shortest path
}

export interface MateGoal {
  kind: 'mate';
  moves: number; // mate in N against perfect defence
}

export interface PromoteGoal {
  kind: 'promote';
  moves: number; // get a queen that can't be taken, in N moves against perfect defence
}

export interface WinGoal {
  kind: 'win';
  moves: number; // be WIN_MARGIN points of material up after black's reply, within N moves
}

export type Goal = PathGoal | MateGoal | PromoteGoal | WinGoal;

export interface Level {
  width: number;
  height: number;
  pieces: Record<string, string>; // uppercase = white, lowercase = black
  goal: Goal;
}

export interface ChapterInfo {
  id: string;
  world: string; // the real chess skill this chapter trains
  title: string;
  intro: string; // shown above every level of the chapter
}

export interface Chapter extends ChapterInfo {
  levels: Level[];
}

