const data = generated as unknown as Record<string, Level[]>; // JSON types `kind` as plain string

export const CHAPTERS: Chapter[] = CHAPTER_INFO.map((info) => ({ ...info, levels: data[info.id] ?? [] }));

export function goalText(goal: Goal): string {
  const s = goal.moves === 1 ? '' : 's';
  switch (goal.kind) {
    case 'path': return `Reach the gold square in ${goal.moves} move${s}.`;
    case 'mate': return `Mate in ${goal.moves}.`;
    case 'promote': return `Promote safely in ${goal.moves} move${s}.`;
    case 'win': return `Win material in ${goal.moves} move${s}.`;
  }
}
